import React, { useEffect, useRef } from 'react';

export default function CountyMap() {
  const mapRef = useRef(null);

  useEffect(() => {
    if (!window.L) return; // Leaflet not loaded yet

    const L = window.L;
    if (mapRef.current) return;

    mapRef.current = L.map('map').setView([-1.0, 36.8], 6);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 18,
      attribution: '&copy; OpenStreetMap contributors'
    }).addTo(mapRef.current);

    // fetch county language metadata and geojson, then render with interactivity
    Promise.all([
      fetch('http://127.0.0.1:8000/api/counties/').then((r) => r.json()),
      fetch('http://127.0.0.1:8000/api/geojson/kenya_counties/').then((r) => r.json()),
    ])
      .then(([counties, data]) => {
        const langMap = {};
        counties.forEach((c) => {
          langMap[c.name.toLowerCase()] = c.languages || [];
        });

        L.geoJSON(data, {
          style: () => ({ color: '#2c7bb6', weight: 2, fillOpacity: 0.3 }),
          onEachFeature: (feature, layer) => {
            const name = (feature.properties && feature.properties.name) || 'County';
            const langs = langMap[name.toLowerCase()] || [];
            const popup = `<strong>${name}</strong><br/>Languages: ${langs.join(', ')}`;
            layer.bindPopup(popup);

            layer.on('mouseover', function () { this.setStyle({ weight: 4, color: '#d1495b', fillOpacity: 0.5 }); this.openPopup(); });
            layer.on('mouseout', function () { this.setStyle({ weight: 2, color: '#2c7bb6', fillOpacity: 0.3 }); this.closePopup(); });

            layer.on('click', function () {
              const detailsEl = document.getElementById('county-details');
              if (detailsEl) {
                detailsEl.innerHTML = `<p><strong>${name}</strong></p><p><strong>Population:</strong> ${langMap[name.toLowerCase()] && langMap[name.toLowerCase()].population ? langMap[name.toLowerCase()].population : 'Unknown'}</p><p><strong>Languages:</strong> ${langs.join(', ')}</p>`;
              }
            });
          }
        }).addTo(mapRef.current);
      })
      .catch((err) => console.error('GeoJSON or counties load failed', err));
  }, []);

  return (
    <div style={{ height: '480px', width: '100%', marginBottom: '1rem' }} id="map"></div>
  );
}
